package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.DomainNetwork;import dev.redstoneengineering.physics.NetworkKernel;import dev.redstoneengineering.physics.RuntimeIntStore;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.BlockGetter;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** 3-D glowglass fiber. Passive fiber has two ends; optical branching requires Splitter. */
public class OpticalFiberBlock extends ConnectedCableBlock{private static final String KEY="optical_fiber";public OpticalFiberBlock(Properties p){super(p);}@Override public MapCodec<OpticalFiberBlock> codec(){return RedstoneEngineering.OPTICAL_FIBER_CODEC.value();}@Override protected boolean canConnectTo(BlockGetter l,BlockPos p,Direction d,BlockState n){return TransmissionTopology.opticalPort(n,d);}public static void setOptical(Level l,BlockPos p,int i,int c,boolean v){int[]r=RuntimeIntStore.get(l,KEY,p,3);r[0]=v?Math.max(0,Math.min(15,i)):0;r[1]=v?Math.max(0,Math.min(15,c)):0;r[2]=v&&r[0]>0?1:0;}public static int intensity(Level l,BlockPos p){return RuntimeIntStore.get(l,KEY,p,3)[0];}public static int channel(Level l,BlockPos p){return RuntimeIntStore.get(l,KEY,p,3)[1];}public static boolean valid(Level l,BlockPos p){return RuntimeIntStore.get(l,KEY,p,3)[2]==1;}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,net.minecraft.world.level.block.Block b,BlockPos np,boolean m){super.neighborChanged(s,l,p,b,np,m);if(l instanceof ServerLevel sl)DomainNetwork.recomputeOptical(sl,p);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)DomainNetwork.recomputeOptical(sl,p);}@Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState ns,boolean m){if(!s.is(ns.getBlock()))RuntimeIntStore.remove(l,KEY,p);super.onRemove(s,l,p,ns,m);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){String t=topologyValid(s)?(valid(l,p)?"Glowglass fiber | I="+intensity(l,p)+"/15 | channel="+channel(l,p):"Glowglass fiber | DARK / channel conflict"):"OPTICAL TOPOLOGY ERROR — passive fiber cannot branch; use Optical Splitter";pl.displayClientMessage(Component.literal(t+" | "+NetworkKernel.summary(l,"optical")),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
